inline const PlayerNativeSlot* FindCF1PlayerNativeSlot(int format,int type,int sheet,int frame) {
    for(const auto& slot:CF1PlayerNativeSlots)
        if(slot.format==format && slot.type==type && slot.sheet==sheet && slot.frame==frame)return &slot;
    return nullptr;
}
inline bool IsCF1PlayerAnimation(int animation) {
    switch(animation){case 0:case 1:case 2:case 3:case 5:case 6:case 7:case 9:case 10:case 50:case 51:case 52:case 90:case 91:return true;default:return false;}
}
